from collections import deque

def get_connected_components(grid):
    n, m = len(grid), len(grid[0])
    visited = [[False] * m for _ in range(n)]
    components = []

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 5 and not visited[r][c]:
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 5 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append(component)
    return components

